gV6(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 JPG, PNG, WebP \u0438\u043b\u0438 PDF \u0434\u043e 5 \u041c\u0411. \u041f\u0440\u043e\u0444\u0438\u043b\u044c \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0434\u043e 20 \u0444\u0430\u0439\u043b\u043e\u0432."},
gV9(){return"\u0424\u0430\u0439\u043b \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d"},
gVa(){return"\u0424\u0430\u0439\u043b\u043e\u0432 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442."},
gVB(){return"\u043f\u043e\u043a\u0430 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u044b"},
gVD(){return"\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044e \u0438\u043b\u0438 \u043a\u043e\u0434\u0443 \u044f\u0437\u044b\u043a\u0430"},
gVC(){return"\u041f\u043e\u0434\u0445\u043e\u0434\u044f\u0449\u0438\u0435 \u044f\u0437\u044b\u043a\u0438 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u044b"},
gVs(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0441\u0430\u043c\u043e\u0433\u043e \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0430"},
gVt(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0441\u0430\u043c\u043e\u0433\u043e \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u0430"},
gVw(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u043e \u0437\u0430\u043a\u0430\u0437\u0447\u0438\u043a\u0435"},
gVi(){return"\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u043e \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u0435"},
gVb(){return"\u0412\u0441\u0435"},
gVe(){return"\u0423\u0441\u043f\u0435\u0448\u043d\u044b\u0435"},
gVc(){return"\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043d\u044b\u0435"},
gVd(){return"\u0416\u0430\u043b\u043e\u0431\u044b"},
gVz(){return"\u042f\u0437\u044b\u043a\u0438"},
