gBH(){return"\u0423\u0441\u0456 \u043e\u043f\u043b\u0430\u0442\u0438 \u0442\u0430 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0456"},
