gBq(){return"\u041e\u043f\u043b\u0430\u0442\u0430 \u0432\u043a\u043b\u044e\u0447\u0430\u0454 \u043f\u043e\u0434\u0430\u0442\u043e\u043a \u0456\u0437 \u043f\u0440\u043e\u0434\u0430\u0436\u0443"},
